def sequence_is_i_only(n_i: int, n_off_i: int) -> bool:
    """True iff N_I>=1 and N_off_I=0."""
    return n_i >= 1 and n_off_i == 0


def sequence_is_hapax(n_i: int, n_off_i: int) -> bool:
    """True iff N_I==1 and N_off_I=0."""
    return n_i == 1 and n_off_i == 0


def leaking_116grams(
    sequences: tuple[tuple[str, ...], ...],
    n_off_i: tuple[int, ...],
) -> tuple[tuple[str, ...], ...]:
    """Next 6-grams with N_off_I>0 in leftover-matching leftover-6 remaining site order."""
    return tuple(
        gram
        for gram, off in zip(sequences, n_off_i, strict=True)
        if off > 0
    )


def leftover_next116_survey_rows() -> list[dict]:
    """Per leftover-matching leftover-6 remaining site-with-next6 survey rows."""
    rows = []
    for gram, parent, matching, leftover6, n_on, n_off, n_ex, hits, off_counts, off_tabs, hapax in zip(
        STANDING_SEQUENCES,
        STANDING_PARENT_6GRAMS,
        STANDING_LEFTOVER_MATCHING_SITES_EACH,
        STANDING_LEFTOVER_MATCHING_6GRAM_SITES_WITH_NEXT116,
        STANDING_N_I_EACH,
        STANDING_N_OFF_I_EACH,
        STANDING_N_EXTRA_EACH,
        STANDING_HITS_BY_TABLET,
        STANDING_OFF_I_BY_TABLET,
        STANDING_OFF_I_TABLETS_WITH_HITS,
        STANDING_HAPAX_EACH,
        strict=True,
    ):
        rows.append(
            {
                "tokens116_next": list(gram),
                "parent_6gram": list(parent),
                "leftover_matching_next116_sites": [list(site) for site in matching],
                "leftover_matching_6gram_site": list(leftover6),
                "leftover_matching_count": len(matching),
                "N_I": n_on,
                "N_on_I": n_on,
                "ia_hits": n_on,
                "ib_hits": STANDING_IB_HITS,
                "N_off_I": n_off,
                "N_leak": n_off,
                "N_extra": n_ex,
                "hits_by_tablet": list(hits),
                "off_i_by_tablet": list(off_counts),
                "off_i_tablets_with_hits": list(off_tabs),
                "i_only": n_off == 0 and n_on >= 1,
                "hapax": hapax,
            }
        )
    return rows


def i_leftover_n6_remaining_after_090_076_remaining_after_430_076_remaining_after_076_020_remaining_after_076_010_next_116grams_all_i_only(
    n_i: tuple[int, ...],
    n_off_i: tuple[int, ...],
    sequences: tuple[tuple[str, ...], ...] = STANDING_SEQUENCES,
    expected_n: int = STANDING_N,
    leftover_sites: tuple[tuple[str, str, int], ...] | None = None,
    next_96grams: tuple[tuple[str, ...] | None, ...] | None = None,
    leftovers: tuple[tuple[tuple[str, ...], int, int, tuple], ...] | None = None,
    i_sides: dict | None = None,
) -> bool:
    """True iff all leftover remaining-after-076-010 leftover 6-gram next 6-grams are I-only.

    Claim holds only if leftover matching leftover-6 remaining sites
    still compute as those 18, every leftover matching leftover-6
    remaining site has one hundred sixteen following tokens so the 116-gram set is
    complete relative to N=18, the eighteen leftover 6-grams still
    compute, and every next 27-gram has N_I>=1 and N_off_I=0. Extra
    I does not make the claim lose. Incomplete set is LOSE. Nested
    leftover 6-gram / leftover 6-gram next 1-gram LOSE / leftover
    6-gram next 2-gram LOSE / leftover-6 extra-I next2 peels /
    leftover-6 extra-I leak next1 peels / leftover-5 next 3-gram
    HOLD do not make this claim lose.
    """
    if leftovers is None:
        leftovers = leftover_n4_rows()
    remaining_6grams = leftover_remaining_6grams_distinct(leftovers, i_sides)
    if leftover_sites is None:
        leftover_sites = leftover_matching_6gram_sites(leftovers)
    if next_96grams is None:
        next_96grams = leftover_6gram_next_116grams(i_sides, leftover_sites, remaining_6grams)
    existing = tuple(gram for gram in next_96grams if gram is not None)
    return (
        remaining_6grams == CYCLE457_SEQUENCES
        and leftover_sites == STANDING_LEFTOVER_MATCHING_6GRAM_SITES
        and len(leftover_sites) == expected_n
        and None not in next_96grams
        and len(next_96grams) == expected_n
        and existing == sequences
        and len(n_i) == expected_n
        and len(n_off_i) == expected_n
        and all(
            sequence_is_i_only(on, off)
            for on, off in zip(n_i, n_off_i, strict=True)
        )
    )


